import {IDS,EQUIPMENT,OWNERS,RECIPES,freshState,restoreState,accessible,amount,load,transfer,craft,craftBlocker} from './game-model.mjs';
import {startInventoryGamepad} from './gamepad.js';
import {itemIcon} from './item-icons.mjs';
import {StandingCharacterViewer} from './character-viewer.js';

const $=s=>document.querySelector(s),html=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SAVE='arc-dust-game-inventory-v1',PREFS='arc-dust-game-settings-v1';
let state=freshState(),catalog=new Map(),page='inventory',owner='booter',selected='fitted-0',recipe='battery',search='',filter='',sort='name',referenceId=null,saveBlocked=false;
let settings={large:false,motion:false},loaded=false;
const ownerPages={inventory:'booter',legger:'legger',storage:'chest'},ownerSelections={};
const mapPlaces=[{id:'booter',label:'Booter',x:34,y:59,icon:'●',description:'Player marker. Position is illustrative; the browser has no live world connection.'},{id:'legger',label:'The Legger',x:46,y:64,icon:'◇',description:'Companion marker. This diagram does not establish actual range, routes or physical access.'},{id:'camp',label:'Camp',x:66,y:34,icon:'△',description:'Sample camp marker. Storage and workstation contents remain owned by their existing sample systems.'}];
let mapSelection='booter',waypoint=null,mapZoom=1;
const itemName=id=>catalog.get(id)?.['Item name']||id;
const symbol=id=>id===IDS.ore?'⬡':id===IDS.dust||id===IDS.algae?'◉':id===IDS.empty?'▥':id===IDS.charged?'ϟ':id===IDS.cloak||id===IDS.jacket?'⋈':id===IDS.grapple?'⌁':id===IDS.dig?'⚒':id===IDS.camp?'△':'◇';
const characterViewer=new StandingCharacterViewer(id=>{const entry=state.entries.find(e=>e.owner==='booter'&&e.item===id);if(entry){selected=entry.key;render();}});
const say=text=>{$('#message').textContent=text;};
function persist(){if(saveBlocked)return;try{localStorage.setItem(SAVE,JSON.stringify(state));}catch{say('Browser storage is unavailable. This session works, but changes will not survive a reload.');}}
function commit(next,message){state=next;render();say(message);persist();}
function run(action){try{action();}catch(error){say(error.message);}}
function heading(kicker,title,description,tag='SAMPLE EXPEDITION'){return `<div class="heading"><div><div class="eyebrow">${html(kicker)}</div><h1>${html(title)}</h1><p>${html(description)}</p></div><span class="tag">${tag}</span></div>`;}
function accessControls(){return `<div class="access"><div class="eyebrow">STUDY ACCESS CONTROLS</div>${[['legger','Legger nearby'],['chest','Chest nearby'],['station','Station nearby']].map(([id,label])=>`<label><input type="checkbox" data-near="${id}" ${state.near[id]?'checked':''}>${label}</label>`).join('')}<p>Toggle proximity to explore availability. Inspection never grants access.</p></div>`;}
function rail(kind='owners'){
  if(kind!=='owners')return `<aside class="rail"><div class="eyebrow">WORKSHOP</div>${RECIPES.map(r=>`<button data-recipe="${r.id}" class="${recipe===r.id?'active':''}">${r.station}<small>${r.id==='battery'?'ASSEMBLY':'PROCESSING'}</small></button>`).join('')}<p class="notice">Select a station here. Bumpers and triggers always switch the top menu tabs.</p></aside>`;
  const entries=state.entries.filter(e=>e.owner===owner),l=load(state,owner,catalog);
  return `<aside class="rail character-card"><div class="eyebrow">${owner==='booter'?'FIELD KIT':owner==='legger'?'COMPANION LOADOUT':'LOCAL STORAGE'}</div><div class="owner-emblem" aria-hidden="true">${owner==='booter'?'◈':owner==='legger'?'♜':'▤'}</div><h2>${html(OWNERS[owner])}</h2><p>${owner==='booter'?'Six fitted tools and garments. Four pockets for the journey.':owner==='legger'?'The expedition’s finite, physically present carrier.':'A local store for the supplies and materials you leave at camp.'}</p><dl><dt>Occupied spaces</dt><dd>${entries.length} / ${owner==='booter'?10:owner==='legger'?12:24}</dd><dt>Access</dt><dd class="${accessible(state,owner)?'good':'blocked'}">${accessible(state,owner)?'Available':'Out of reach'}</dd>${owner==='legger'?`<dt>Cargo mass</dt><dd>${l.mass.toFixed(1)}${l.unknown?' + unknown':''} / 92</dd>`:''}</dl><div class="eyebrow">${owner==='booter'?'READY TO TRAVEL':owner==='legger'?'CARGO MANIFEST':'CAMP SUPPLIES'}</div><p class="notice">${owner==='booter'?'Resources travel with the Legger.':owner==='legger'?'Each stack occupies a cargo mount.':'Items remain here until explicitly transferred.'}</p></aside>`;
}
function tools(reference=false){const categories=[...new Set((reference?[...catalog.values()]:state.entries.filter(e=>e.owner===owner).map(e=>catalog.get(e.item)).filter(Boolean)).map(i=>i.Category))].sort();return `<div class="toolbar"><input id="game-search" type="search" aria-label="Search ${reference?'reference':'possessions'}" placeholder="Search ${reference?'all definitions':'this inventory'}…" value="${html(search)}"><select id="game-filter" aria-label="Filter items"><option value="">All categories</option>${categories.map(c=>`<option ${filter===c?'selected':''}>${html(c)}</option>`).join('')}<option value="favourite" ${filter==='favourite'?'selected':''}>Favourites</option><option value="protected" ${filter==='protected'?'selected':''}>Protected</option></select><select id="game-sort" aria-label="Sort view"><option value="name" ${sort==='name'?'selected':''}>Name A–Z</option><option value="quantity" ${sort==='quantity'?'selected':''}>Quantity</option></select></div>`;}
function matches(item,entry){return (!search||[item?.['Item name'],item?.Category,item?.Purpose,item?.['Search terms'],entry?.item].join(' ').toLowerCase().includes(search.toLowerCase()))&&(!filter||(filter==='favourite'?state.favourites.includes(entry?.key):filter==='protected'?state.protected.includes(entry?.key):item?.Category===filter));}
function row(entry){return `<button data-entry="${html(entry.key)}" class="${selected===entry.key?'selected':''}" aria-pressed="${selected===entry.key}"><span class="symbol" aria-hidden="true">${symbol(entry.item)}</span><span><strong>${html(itemName(entry.item))}</strong><small>${html(catalog.get(entry.item)?.Category||'Definition unavailable')}${entry.dust?` · ${entry.dust} contained dust`:''}${state.protected.includes(entry.key)?' · Protected':''}${state.favourites.includes(entry.key)?' · Favourite':''}</small></span><span class="quantity">${entry.qty}<small>${entry.instance?'INSTANCE':'UNITS'}</small></span></button>`;}
function portrait(){return `<aside class="character-panel"><div class="section-label">CHARACTER <span>BOOTER</span></div><div class="character-stage" id="character-stage"><div class="viewer-halo"></div><span class="viewer-model-label">PROTOTYPE MODEL</span><span class="viewer-angle">342°</span><div class="viewer-state">Loading character…</div></div><div class="rotate-controls"><button data-turn="-30" aria-label="Rotate character left">↶</button><span>ROTATE CHARACTER</span><button data-turn="30" aria-label="Rotate character right">↷</button><button data-turn="front" class="reset-view" aria-label="Reset character view">Front</button></div><div class="character-caption"><strong>Booter</strong><span>Expedition loadout</span></div></aside>`;}
function slot(index,label){
  const e=state.entries.find(e=>e.owner==='booter'&&e.slot===index);
  return `<button class="gear-tile ${e?'':'empty-slot'} ${e?.key===selected?'selected':''}" ${e?`data-entry="${html(e.key)}" aria-pressed="${e.key===selected}" aria-label="Inspect ${html(itemName(e.item))}"`:'disabled'}><span class="slot-label">${html(label)}</span><span class="tile-icon">${itemIcon(e?.item||EQUIPMENT[index]?.[1]||'empty')}</span><span class="tile-name">${e?html(itemName(e.item)):'Empty'}</span>${e?`<span class="tile-count">${state.protected.includes(e.key)?'◆':index<6?'FITTED':'×'+e.qty}</span>`:''}</button>`;
}
function cargoTile(e,index){return e?`<button class="gear-tile cargo-tile ${selected===e.key?'selected':''}" data-entry="${html(e.key)}" aria-pressed="${selected===e.key}" aria-label="Inspect ${html(itemName(e.item))}"><span class="slot-label">${String(index+1).padStart(2,'0')}</span><span class="tile-icon">${itemIcon(e.item)}</span><span class="tile-name">${html(itemName(e.item))}</span><span class="tile-count">${e.dust?e.dust+' DUST':'×'+e.qty}${state.protected.includes(e.key)?' ◆':''}</span></button>`:`<div class="gear-tile empty-slot cargo-tile" aria-label="Empty cargo space"><span class="slot-label">${String(index+1).padStart(2,'0')}</span><span class="empty-plus">+</span></div>`;}
function inventory(){
  const entries=state.entries.filter(e=>e.owner===owner&&matches(catalog.get(e.item),e)).sort((a,b)=>sort==='quantity'?b.qty-a.qty||itemName(a.item).localeCompare(itemName(b.item)):itemName(a.item).localeCompare(itemName(b.item)));
  const l=load(state,owner,catalog),capacity=owner==='booter'?10:owner==='legger'?12:24,all=state.entries.filter(e=>e.owner===owner);
  const title=owner==='booter'?'Booter inventory':owner==='legger'?'Legger loadout':'Camp storage';
  const equipped=owner==='booter'&&!search&&!filter;
  const left=owner==='booter'?portrait():`<aside class="storage-overview"><div class="section-label">${owner==='legger'?'COMPANION':'CAMP'}</div><div class="storage-emblem">${owner==='legger'?'♜':'▤'}</div><h2>${owner==='legger'?'The Legger':'Camp chest'}</h2><div class="load-number">${all.length}<span> / ${capacity}</span></div><span class="muted">cargo spaces used</span>${owner==='legger'?`<div class="load-mass">${l.mass.toFixed(1)}${l.unknown?' + ?':''}<small> / 92 MASS</small></div>`:''}<div class="meter"><span style="width:${owner==='legger'?Math.min(100,l.mass/92*100):all.length/capacity*100}%"></span></div><span class="access-tag ${accessible(state,owner)?'good':'blocked'}">${accessible(state,owner)?'● WITHIN REACH':'○ INSPECTION ONLY'}</span></aside>`;
  return heading('',title,'')+`<div class="inventory-workspace">${left}<section class="gear-area">${owner==='booter'?'':tools()}${!accessible(state,owner)?'<p class="notice blocked">Out of reach. Inspection only.</p>':''}${equipped?`<div class="section-label">EQUIPMENT <span>6 DESIGNATED SLOTS</span></div><div class="equipment-grid">${EQUIPMENT.map(([label],i)=>slot(i,label)).join('')}</div><div class="section-label supplies-label">SUPPLIES <span>${all.filter(e=>e.slot>=6).length} / 4</span></div><div class="supply-grid">${[6,7,8,9].map((i)=>slot(i,`Pocket ${i-5}`)).join('')}</div>`:`<div class="section-label">${owner==='booter'?'SUPPLIES':'CARGO'} <span>${all.length} / ${capacity}</span></div><div class="cargo-grid ${owner==='chest'?'chest-grid':''}">${(search||filter?entries:Array.from({length:capacity},(_,i)=>entries[i])).map(cargoTile).join('')||'<p class="empty">No matching items.</p>'}</div>`}<div class="inventory-receipt">${owner==='booter'?'Personal gear and field supplies':owner==='legger'?'Finite cargo · physical access required':'Local storage'}<span>${accessible(state,owner)?'ACCESSIBLE':'OUT OF REACH'}</span></div></section>${inspect()}</div>`;
}
function inspect(){
  const entry=state.entries.find(e=>e.key===selected&&e.owner===owner);
  if(!entry)return '<aside class="panel item-inspector"><div class="section-label">INSPECT</div><p class="empty">Select an item.</p></aside>';
  const item=catalog.get(entry.item),protectedItem=state.protected.includes(entry.key),favourite=state.favourites.includes(entry.key),equipment=EQUIPMENT.find(([,id])=>id===entry.item);
  const field=(k,v)=>`<dt>${k}</dt><dd>${html(v)}</dd>`;
  return `<aside class="panel item-inspector"><div class="section-label">INSPECT <span>${entry.instance?'EQUIPMENT':'SUPPLY / RESOURCE'}</span></div><div class="inspect-art">${itemIcon(entry.item)}</div><h2>${html(itemName(entry.item))}</h2><div class="item-subtitle">${html(equipment?.[0]||item?.Category||'Item')} ${entry.owner==='booter'&&entry.slot<6?'· FITTED':''}</div><p class="item-purpose">${html(item?.Purpose||'Expedition equipment.')}</p><dl>${field('Location',OWNERS[entry.owner])}${field('Quantity',entry.qty)}${entry.dust?field('Contained dust',entry.dust):''}${item?.['Mass (game units)']!=null?field('Unit mass',item['Mass (game units)']):''}${field('Access',accessible(state,entry.owner)?'Available':'Out of reach')}</dl><div class="actions item-marks"><button data-action="favourite" class="${favourite?'active':''}" aria-pressed="${favourite}">${favourite?'★ Favourite':'☆ Favourite'}</button><button data-action="protect" class="${protectedItem?'active':''}" aria-pressed="${protectedItem}">${protectedItem?'◆ Protected':'Protect'}</button></div><div class="transfer-label">MOVE TO</div><div class="actions transfer-actions">${Object.entries(OWNERS).filter(([id])=>id!==owner).map(([id,label])=>`<button data-transfer="${id}" ${!accessible(state,owner)||!accessible(state,id)||protectedItem||entry.item===IDS.algae?'disabled':''}>${id==='legger'?'Legger':id==='chest'?'Camp chest':'Booter'}</button>`).join('')}</div>${entry.item===IDS.algae?'<p class="inline-note">Living reserve · attached</p>':''}<button class="help-link" data-reference="${html(entry.item)}">Reference & uses ↗</button>${RECIPES.filter(r=>r.output===entry.item||r.id==='battery'&&entry.item===IDS.ore||r.id==='charge'&&[IDS.empty,IDS.dust].includes(entry.item)).map(r=>`<button class="help-link" data-craft-link="${r.id}">${r.output===entry.item?'Make':'Used in'}: ${html(r.name)} ↗</button>`).join('')}</aside>`;
}
function crafting(){const r=RECIPES.find(r=>r.id===recipe),blocker=craftBlocker(state,r.id,catalog),ore=state.entries.filter(e=>e.owner==='chest'&&e.item===IDS.ore),oreEligible=ore.filter(e=>accessible(state,e.owner)&&!state.protected.includes(e.key)).reduce((n,e)=>n+e.qty,0),dust=state.entries.filter(e=>e.item===IDS.dust&&accessible(state,e.owner)&&!state.protected.includes(e.key)).reduce((n,e)=>n+(e.dust||0),0);
  return heading('CAMP / CRAFTING','Make what you need.','Inspect the route, check local stock, choose the next useful action.')+`<div class="workspace">${rail('recipes')}<section>${RECIPES.map(rec=>`<button class="recipe-card ${r.id===rec.id?'active':''}" data-recipe="${rec.id}"><div class="eyebrow">${rec.station} / ${craftBlocker(state,rec.id,catalog)?'REQUIREMENTS UNMET':'READY HERE'}</div><strong>${rec.name}</strong><small>${rec.description}</small></button>`).join('')}<p class="notice">Two explicit Camp Loop sample operations. Prototype costs are not settled production balance. The refinery study applies conversion directly; Unity’s physical docking and deployment are not simulated here.</p><p class="notice">The remaining catalogue is reference material. Unresolved quantities, sources and facilities never become zero-cost recipes.</p></section><aside class="panel"><div class="eyebrow">${r.station} / RECIPE</div><h2>${r.name}</h2><p>${r.description}</p>${r.id==='battery'?`<div class="requirements"><span>Ironstone Ore<br><small>Eligible in camp chest / required</small></span><strong>${oreEligible} / 4</strong></div><div class="requirements"><span>Known owned across locations</span><strong>${amount(state,IDS.ore)}</strong></div>`:`<div class="requirements"><span>Contained dust<br><small>10 must be in one eligible canister</small></span><strong>${dust} / 10</strong></div><div class="requirements"><span>Eligible empty batteries</span><strong>${amount(state,IDS.empty,true)} / 1</strong></div>`}<div class="requirements"><span>Output destination</span><strong>Booter pocket</strong></div><p class="notice ${blocker?'blocked':'good'}">${html(blocker||'Ready here · requirements and output space verified.')}</p><div class="actions"><button data-action="craft" ${blocker?'disabled':''}>${r.id==='battery'?'Craft one':'Refine & charge'}</button><button data-action="track">Track project</button></div></aside></div>`;
}
function projects(){
  const oreNeed=state.projects.filter(p=>p.recipe==='battery').reduce((n,p)=>n+p.qty*4,0),emptyNeed=state.projects.filter(p=>p.recipe==='charge').reduce((n,p)=>n+p.qty,0),dustNeed=emptyNeed*10;
  const oreHere=state.entries.filter(e=>e.owner==='chest'&&e.item===IDS.ore&&accessible(state,e.owner)&&!state.protected.includes(e.key)).reduce((n,e)=>n+e.qty,0),dustHere=state.entries.filter(e=>accessible(state,e.owner)&&!state.protected.includes(e.key)).reduce((n,e)=>n+(e.dust||0),0);
  return heading('EXPEDITION / PROJECTS','A reason to gather.','Tracked quantities mean additional outputs to make. Tracking never reserves or consumes stock.')+`<div class="workspace">${rail()}<section>${state.projects.map(p=>{const r=RECIPES.find(r=>r.id===p.recipe);return `<article class="project"><div class="eyebrow">${r.station} / TRACKED</div><h2>${r.name}</h2><label>Make <input type="number" min="1" max="99" value="${p.qty}" data-project="${p.recipe}" aria-label="Quantity for ${r.name}"> more</label><p>${p.recipe==='battery'?`${p.qty*4} Ironstone Ore from the camp chest`:`${p.qty} empty batteries and ${p.qty*10} contained dust`}</p><div class="actions"><button data-craft-link="${p.recipe}">View recipe</button><button data-remove="${p.recipe}">Untrack</button></div></article>`;}).join('')||'<p class="empty">No tracked projects yet.<br>Open Crafting and choose Track project to build a gathering list.</p>'}</section><aside class="panel"><div class="eyebrow">COMBINED DIRECT REQUIREMENTS</div><h2>Gathering list</h2>${[[IDS.ore,oreNeed,oreHere],[IDS.empty,emptyNeed,amount(state,IDS.empty,true)]].filter(([,need])=>need).map(([id,need,here])=>`<div class="requirements"><span>${html(itemName(id))}<br><small>${here} eligible · ${amount(state,id)} known owned</small></span><strong>${Math.max(0,need-here)} missing<br><small>${need} required</small></strong></div>`).join('')}${dustNeed?`<div class="requirements"><span>Contained dust<br><small>${dustHere} eligible</small></span><strong>${Math.max(0,dustNeed-dustHere)} missing<br><small>${dustNeed} required</small></strong></div>`:''}<p class="notice">Counts combine each selected route once. Empty batteries allocated to charging are not assumed to exist until actually crafted. Each charge also needs 10 dust in a single canister; the total alone cannot prove readiness.</p><p class="notice">After a successful craft, the tracked remaining output count decreases by one.</p></aside></div>`;
}
function reference(){const items=[...catalog.values()].filter(item=>matches(item,null)).sort((a,b)=>itemName(a['Item ID']).localeCompare(itemName(b['Item ID']))),item=catalog.get(referenceId),uses=RECIPES.filter(r=>r.output===referenceId||r.id==='battery'&&referenceId===IDS.ore||r.id==='charge'&&[IDS.empty,IDS.dust].includes(referenceId));return heading('KNOWLEDGE / ITEM REFERENCE','Understand the haul.','All catalogue definitions for this design study. Listed items are not automatically owned or craftable.','READ ONLY')+`<div class="workspace">${rail()}<section>${tools(true)}<p class="reference-count">${items.length} definitions · Tier is not rarity · Showing up to 100 matches</p><div class="manifest">${items.slice(0,100).map(i=>`<button data-reference="${html(i['Item ID'])}" class="${referenceId===i['Item ID']?'selected':''}"><span class="tile-icon">${itemIcon(i['Item ID'])}</span><span><strong>${html(i['Item name'])}</strong><small>${html(i.Category)} · ${html(i.Tier||'Unassigned')}</small></span><span class="quantity">${amount(state,i['Item ID'])}<small>OWNED</small></span></button>`).join('')||'<p class="empty">No definitions match these filters.</p>'}</div></section><aside class="panel"><div class="eyebrow">CATALOGUE / INFORMATION</div>${item?`<h2>${html(item['Item name'])}</h2><p>${html(item.Purpose||'No purpose recorded.')}</p><dl><dt>Known owned</dt><dd>${amount(state,referenceId)}</dd><dt>Accessible, unprotected</dt><dd>${amount(state,referenceId,true)}</dd><dt>Material tier</dt><dd>${html(item.Tier||'Unassigned')}</dd></dl>${state.entries.filter(e=>e.item===referenceId).map(e=>`<p>${html(OWNERS[e.owner])} · ${e.qty}${accessible(state,e.owner)?'':' · out of reach'}</p>`).join('')}${uses.map(r=>`<button class="help-link" data-craft-link="${r.id}">${r.output===referenceId?'How to make':'Used to make'}: ${r.name} ↗</button>`).join('')}${!uses.length?'<p class="notice">No qualified recipe is included for this item in this study. Catalogue route descriptions are not executable recipes.</p>':''}`:'<p class="empty">Select a definition to inspect its purpose and known locations.</p>'}<p class="notice">Reference only. No workbook deletion, review, artwork editing, item spawning or global storage actions exist in this tab.</p></aside></div>`;}
function mapView(){
  const place=mapPlaces.find(p=>p.id===mapSelection);
  return heading('EXPEDITION / MAP','Know the way back.','A schematic map mockup. These markers are illustrative, not live world positions.','MAP STUDY')+`<div class="map-layout"><section><div class="map-toolbar"><span class="eyebrow">LOCAL AREA / SCHEMATIC</span><div class="actions"><button data-map-zoom="out" ${mapZoom<=1?'disabled':''} aria-label="Zoom map out">−</button><span>${Math.round(mapZoom*100)}%</span><button data-map-zoom="in" ${mapZoom>=2?'disabled':''} aria-label="Zoom map in">+</button></div></div><div class="map-viewport" aria-label="Schematic map"><div class="map-sheet" style="width:${mapZoom*100}%"><svg viewBox="0 0 1000 650" preserveAspectRatio="none" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="1.5"><path d="M-40 170Q190 90 330 220T650 270T1040 80M-40 200Q190 120 330 250T650 300T1040 110M-40 230Q190 150 330 280T650 330T1040 140M-40 260Q190 180 330 310T650 360T1040 170M-40 290Q190 210 330 340T650 390T1040 200M-40 320Q190 240 330 370T650 420T1040 230M-40 350Q190 270 330 400T650 450T1040 260M-40 380Q190 300 330 430T650 480T1040 290M-40 410Q190 330 330 460T650 510T1040 320M-40 440Q190 360 330 490T650 540T1040 350M-40 470Q190 390 330 520T650 570T1040 380"/></g></svg><span class="map-north">N ↑</span>${mapPlaces.map(p=>`<button data-map-marker="${p.id}" class="map-marker ${mapSelection===p.id?'selected':''}" style="left:${p.x}%;top:${p.y}%" aria-pressed="${mapSelection===p.id}"><strong>${p.icon}</strong><span>${html(p.label)}${waypoint===p.id?' · WAYPOINT':''}</span></button>`).join('')}<span class="map-note">SCHEMATIC ONLY / NO TERRAIN OR DISTANCE DATA</span></div></div><p class="notice">Select a marker to inspect it. Zoom for a closer view; the right stick pans the scrollable map when a marker has focus.</p></section><aside class="panel"><div class="eyebrow">MAP / SELECTED MARKER</div><h2>${html(place.label)}</h2><p>${place.description}</p><div class="actions"><button data-action="waypoint">Mark waypoint</button><button data-action="clear-waypoint" ${waypoint?'':'disabled'}>Clear waypoint</button></div><p class="notice">${waypoint?'Waypoint: '+html(mapPlaces.find(p=>p.id===waypoint).label):'No waypoint selected.'} This marker is local to the mockup and does not command movement.</p></aside></div>`;
}
function settingsView(){
  return heading('SYSTEM / SETTINGS','Make it yours.','Adjust the interface, arrange your shortcuts, and return to the expedition.')+`<div class="settings-page"><section class="panel"><div class="eyebrow">INTERFACE / ACCESSIBILITY</div><h2>Readability</h2><label><input type="checkbox" data-setting="large" ${settings.large?'checked':''}>Larger interface text</label><label><input type="checkbox" data-setting="motion" ${settings.motion?'checked':''}>Reduce interface motion</label><p>These preferences apply to this game-menu study.</p><div class="notice">D-pad / left stick: navigate<br>South: select<br>LB / RB or LT / RT: previous / next top tab<br>Right stick: scroll</div></section><section class="panel"><div class="eyebrow">CONTROLS / QUICK ACTIONS</div><h2>Radial shortcuts</h2>${state.radial.map((value,i)=>`<label>Direction ${['↑','→','↓','←'][i]}<select data-radial="${i}">${['Inventory','Crafting','Projects','Deploy dust canister','Make camp','Algae reserve'].map(action=>`<option ${value===action?'selected':''}>${action}</option>`).join('')}</select></label>`).join('')}<p class="notice">Shortcut assignments are saved in this study. Gameplay actions are placeholders.</p></section><section class="panel prototype-settings"><details id="prototype-controls"><summary>Prototype controls</summary><p class="notice">Explore inventory availability without a running game. These switches are study controls.</p>${accessControls()}<button class="reset-button" data-action="reset">Reset sample expedition…</button></details></section></div>`;
}
function render(){
  if(!loaded)return;
  const searchFocus=document.activeElement?.id==='game-search',position=searchFocus?document.activeElement.selectionStart:null;
  const prototypeOpen=$('#prototype-controls')?.open,mapViewport=$('.map-viewport'),mapPosition=mapViewport?{left:mapViewport.scrollLeft,top:mapViewport.scrollTop}:null;
  characterViewer.canvas.remove();
  document.body.dataset.screen=page;
  $('#content').innerHTML=ownerPages[page]?inventory():page==='crafting'?crafting():page==='projects'?projects():page==='map'?mapView():page==='settings'?settingsView():reference();
  if($('#character-stage'))characterViewer.mount($('#character-stage'),state.entries.filter(e=>e.owner==='booter'&&e.slot<6).map(e=>e.item),state.entries.find(e=>e.key===selected)?.item);
  if(prototypeOpen&&$('#prototype-controls'))$('#prototype-controls').open=true;
  if(mapPosition&&$('.map-viewport'))$('.map-viewport').scrollTo(mapPosition);
  document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false');});
  $('#project-count').textContent=state.projects.length;
  if(searchFocus&&$('#game-search')){$('#game-search').focus();try{$('#game-search').setSelectionRange(position,position);}catch{}}
}
function go(next){
  if(state.entries.some(e=>e.key===selected&&e.owner===owner))ownerSelections[owner]=selected;
  page=next;search='';filter='';
  if(ownerPages[page]){owner=ownerPages[page];selected=state.entries.find(e=>e.key===ownerSelections[owner]&&e.owner===owner)?.key||state.entries.find(e=>e.owner===owner)?.key;}
  render();window.scrollTo({top:0,behavior:'instant'});
}
function applySettings(){document.documentElement.classList.toggle('large-text',settings.large);document.documentElement.classList.toggle('reduced-motion',settings.motion);}
function leaveStudy(){if(window.parent!==window)window.parent.location.hash='inventory';else window.location.href='index.html#inventory';}
document.addEventListener('click',event=>run(()=>{
  const button=event.target.closest('button');if(!button||button.disabled)return;
  const d=button.dataset;
  if(d.turn){characterViewer.turn(d.turn==='front'?null:Number(d.turn));return;}
  if(d.page){go(d.page);return;}
  if(d.owner){go(Object.keys(ownerPages).find(p=>ownerPages[p]===d.owner)||'inventory');return;}
  if(d.mapMarker){mapSelection=d.mapMarker;render();document.querySelector(`[data-map-marker="${CSS.escape(mapSelection)}"]`)?.focus();return;}
  if(d.mapZoom){mapZoom=Math.max(1,Math.min(2,mapZoom+(d.mapZoom==='in'?.25:-.25)));render();return;}
  if(d.action==='waypoint'){waypoint=mapSelection;render();say('Waypoint set on the schematic map only.');return;}
  if(d.action==='clear-waypoint'){waypoint=null;render();say('Schematic waypoint cleared.');return;}
  if(d.entry){selected=d.entry;render();document.querySelector(`[data-entry="${CSS.escape(selected)}"]`)?.focus();return;}
  if(d.recipe){recipe=d.recipe;render();return;}
  if(d.craftLink){recipe=d.craftLink;go('crafting');return;}
  if(d.reference){referenceId=d.reference;go('reference');return;}
  if(d.transfer){if(state.entries.find(e=>e.key===selected)?.item===IDS.algae)throw Error('The living algae attachment cannot be removed.');const next=transfer(state,selected,d.transfer,catalog);commit(next,`Transferred to ${OWNERS[d.transfer]}.`);return;}
  if(d.action==='protect'||d.action==='favourite'){
    const key=d.action==='protect'?'protected':'favourites';if(!state.entries.some(e=>e.key===selected))return;
    const next=structuredClone(state);next[key]=next[key].includes(selected)?next[key].filter(k=>k!==selected):[...next[key],selected];commit(next,'Item preference updated in this sample save.');return;
  }
  if(d.action==='craft'){
    const next=craft(state,recipe,catalog),project=next.projects.find(p=>p.recipe===recipe);
    if(project){project.qty--;next.projects=next.projects.filter(p=>p.qty>0);}
    commit(next,`${RECIPES.find(r=>r.id===recipe).name} → Booter supply pocket. Inputs and output committed together.`);return;
  }
  if(d.action==='track'){const next=structuredClone(state);if(!next.projects.some(p=>p.recipe===recipe))next.projects.push({recipe,qty:1});commit(next,'Project tracked. No resources reserved or consumed.');return;}
  if(d.remove){const next=structuredClone(state);next.projects=next.projects.filter(p=>p.recipe!==d.remove);commit(next,'Project removed. Possessions are unchanged.');return;}
  if(d.action==='reset'){$('#reset').showModal();return;}
  if(d.menu==='resume'){$('#menu').close();return;}
  if(d.menu==='radial'||d.menu==='settings'){$('#menu').close();go('settings');return;}
  if(d.menu==='exit'){leaveStudy();return;}
}));
document.addEventListener('input',event=>{if(event.target.id==='game-search'){search=event.target.value;render();}});
document.addEventListener('change',event=>run(()=>{
  const target=event.target,d=target.dataset;
  if(d.near){state.near[d.near]=target.checked;render();persist();say('Access updated. Quantities and ownership are unchanged.');}
  if(target.id==='game-filter'){filter=target.value;render();}
  if(target.id==='game-sort'){sort=target.value;render();}
  if(d.project){const quantity=Number(target.value);if(!Number.isInteger(quantity)||quantity<1||quantity>99){render();throw Error('Choose a quantity from 1 to 99.');}state.projects.find(p=>p.recipe===d.project).qty=quantity;render();persist();}
  if(d.radial!==undefined){state.radial[Number(d.radial)]=target.value;persist();say('Shortcut saved for this study.');}
  if(d.setting){settings[d.setting]=target.checked;applySettings();try{localStorage.setItem(PREFS,JSON.stringify(settings));}catch{say('Settings are session-only because browser storage is unavailable.');}}
}));
$('#open-menu').onclick=()=>$('#menu').showModal();
$('#cancel-reset').onclick=()=>$('#reset').close();
$('#confirm-reset').onclick=()=>{$('#reset').close();saveBlocked=false;state=freshState();owner='booter';selected='fitted-0';go('inventory');persist();say('Sample expedition reset. The item database is unchanged.');};
document.addEventListener('keydown',event=>{
  if(document.querySelector('dialog[open]'))return;
  if(event.key==='Escape'){event.preventDefault();$('#menu').showModal();return;}
  if(/INPUT|SELECT|TEXTAREA/.test(event.target.tagName))return;
  if(event.key==='/'){event.preventDefault();if(!$('#game-search'))go('reference');$('#game-search')?.focus();}
  if(event.key.toLowerCase()==='i')go('inventory');
});
async function init(){
  let recovery='';
  try{const saved=localStorage.getItem(SAVE);if(saved)state=restoreState(JSON.parse(saved));}catch{saveBlocked=true;recovery='Saved study data could not be read. It has been preserved; reset the sample explicitly to replace it.';}
  try{const saved=JSON.parse(localStorage.getItem(PREFS)||'null');if(saved)settings={large:saved.large===true,motion:saved.motion===true};}catch{}
  applySettings();
  try{const response=await fetch('/api/catalog');if(!response.ok)throw Error('The item catalogue is unavailable.');const data=await response.json();catalog=new Map(data.items.map(item=>[item['Item ID'],item]));loaded=true;render();say(recovery||'Loadout ready.');}
  catch(error){$('#content').innerHTML='<p class="empty">Could not read the item catalogue. Keep the local visualizer server running, then reload this tab.</p>';say(error.message);}
}
init().then(()=>{if(loaded)startInventoryGamepad();});
